BEGIN TRANSACTION READ ONLY; SET LOCAL search_path=pg_catalog,public;
SELECT jsonb_build_object('captured_at',now(),'project_database',current_database(),'postgres_version',version(),
'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname) FROM pg_policies p WHERE schemaname='public' AND tablename IN ('hka_messages','hka_profiles','hka_account_roles','hka_guardians','hka_coach_students','hka_link_requests','hka_student_link_codes')),
'api_settings',jsonb_build_object('pgrst.db_schemas',current_setting('pgrst.db_schemas',true),'pgrst.db_extra_search_path',current_setting('pgrst.db_extra_search_path',true)),
'role_database_api_settings',(SELECT coalesce(jsonb_agg(jsonb_build_object('database',d.datname,'role',r.rolname,'settings',s.setconfig)),'[]'::jsonb) FROM pg_db_role_setting s LEFT JOIN pg_database d ON d.oid=s.setdatabase LEFT JOIN pg_roles r ON r.oid=s.setrole WHERE EXISTS(SELECT 1 FROM unnest(s.setconfig) setting WHERE setting LIKE 'pgrst.%')),
'graphql_extension',(SELECT jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname)) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='pg_graphql'),
'collisions',jsonb_build_object('private_schema_exists',to_regnamespace('hka_messaging') IS NOT NULL,'public_message_functions',(SELECT coalesce(jsonb_agg(p.proname),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'hka_message_%')),
'migration_history',(SELECT jsonb_agg(jsonb_build_object('version',version,'name',name) ORDER BY version) FROM supabase_migrations.schema_migrations),
'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('hka_messages','hka_profiles','hka_account_roles','hka_guardians','hka_coach_students','hka_link_requests','hka_student_link_codes')),
'message_grants',(SELECT jsonb_agg(to_jsonb(g)) FROM (SELECT grantee,privilege_type FROM information_schema.role_table_grants WHERE table_schema='public' AND table_name='hka_messages') g),
'column_grants',(SELECT jsonb_agg(to_jsonb(g)) FROM (SELECT table_name,grantee,column_name,privilege_type FROM information_schema.column_privileges WHERE table_schema='public' AND table_name IN ('hka_messages','hka_profiles') AND grantee IN ('anon','authenticated','service_role')) g)
) AS snapshot; COMMIT;

-- Prepared supplementary catalog only; NOT executed during this review.
BEGIN TRANSACTION READ ONLY;
SET LOCAL search_path=pg_catalog,public;
SET LOCAL statement_timeout='20s';
SELECT jsonb_build_object(
 'captured_at',now(),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,'definition',pg_get_constraintdef(c.oid)) ORDER BY c.conrelid::regclass::text,c.conname) FROM pg_constraint c WHERE c.conrelid IN (SELECT cl.oid FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE n.nspname='public' AND cl.relname IN ('hka_messages','hka_profiles','hka_account_roles','hka_guardians','hka_coach_students','hka_link_requests','hka_student_link_codes'))),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',t.tgrelid::regclass::text,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid))),'[]'::jsonb) FROM pg_trigger t WHERE NOT t.tgisinternal AND (t.tgrelid IN (SELECT cl.oid FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE n.nspname='public' AND cl.relname IN ('hka_messages','hka_profiles','hka_account_roles','hka_guardians','hka_coach_students','hka_link_requests','hka_student_link_codes')) OR t.tgrelid='auth.users'::regclass)),
 'functions',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl) ORDER BY n.nspname,p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname='public' AND p.proname IN ('hka_role','hka_admin','hka_active','hka_teach','hka_view_student','hka_signup_profile','hka_has_purpose','hka_coaches')) OR (n.nspname='auth' AND p.proname='uid') OR (n.nspname='graphql_public' AND p.proname='graphql')),
 'indexes',(SELECT jsonb_agg(to_jsonb(i)) FROM (SELECT tablename,indexname,indexdef FROM pg_indexes WHERE schemaname='public' AND tablename IN ('hka_messages','hka_account_roles')) i),
 'owner_privileges',jsonb_build_object('current_user',current_user,'replication_role',current_setting('session_replication_role'),'superuser',(SELECT rolsuper FROM pg_roles WHERE rolname=current_user),'bypassrls',(SELECT rolbypassrls FROM pg_roles WHERE rolname=current_user),'create_schema',has_database_privilege(current_user,current_database(),'CREATE'),'public_create',has_schema_privilege(current_user,'public','CREATE'),'auth_usage',has_schema_privilege(current_user,'auth','USAGE'),'auth_user_id_read',has_column_privilege(current_user,'auth.users','id','SELECT'),'auth_user_confirmation_read',has_column_privilege(current_user,'auth.users','email_confirmed_at','SELECT'),'auth_uid_execute',has_function_privilege(current_user,'auth.uid()','EXECUTE')),
 'graphql_function_count',(SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='graphql'),
 'default_acls',(SELECT jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'type',d.defaclobjtype,'acl',d.defaclacl)) FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE n.nspname='public' OR d.defaclnamespace=0),
 'role_memberships',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'member',m.rolname)) FROM pg_auth_members am JOIN pg_roles r ON r.oid=am.roleid JOIN pg_roles m ON m.oid=am.member WHERE m.rolname IN ('anon','authenticated','service_role','authenticator','postgres')),
 'realtime_message_publications',(SELECT jsonb_agg(to_jsonb(p)) FROM (SELECT pubname,schemaname,tablename FROM pg_publication_tables WHERE schemaname='public' AND tablename='hka_messages') p)
) AS snapshot;
COMMIT;
